Brief:
Un jeu de réflexion au tour par tour, sans aucune pression, où il faut pourtant répondre en moins de trois secondes avant la fin du chrono.

Plan:
{"gameType":"stage-clear","input":"tap-anywhere","lang":"fr","loop":"À chaque tour, choisis la bonne case parmi celles affichées avant que le chrono de trois secondes ne s'écoule. Enchaîne les tours pour progresser ; une réponse trop lente ou fausse met fin à la partie.","slug":"trois-secondes","style":"chalkboard","title":"Trois Secondes"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Trois Secondes</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #2f3e3a;
11|     overflow: hidden;
12|     font-family: "Comic Sans MS", "Segoe UI", sans-serif;
13|   }
14|   canvas {
15|     display: block;
16|     touch-action: none;
17|   }
18| </style>
19| </head>
20| <body>
21| <canvas id="game"></canvas>
22| <script>
23| // ---- Bridge helper (verbatim) ----
24| const CARTRIDGE = {
25|   send(type, payload = {}) {
26|     window.parent.postMessage(
27|       { source: "cartridge", v: 1, type, payload },
28|       "*",
29|     );
30|   },
31| };
32| 
33| window.addEventListener("message", (event) => {
34|   const data = event.data;
35|   if (!data || data.source !== "cartridge-host") return;
36|   if (data.type === "pause") paused = true;
37|   if (data.type === "resume") paused = false;
38|   if (data.type === "reset") backToTitle();
39| });
40| 
41| // ---- Setup canvas ----
42| const canvas = document.getElementById("game");
43| const ctx = canvas.getContext("2d");
44| canvas.style.touchAction = "none";
45| 
46| let dpr = Math.max(1, window.devicePixelRatio || 1);
47| let W = 0, H = 0;
48| 
49| function resize() {
50|   W = window.innerWidth;
51|   H = window.innerHeight;
52|   dpr = Math.max(1, window.devicePixelRatio || 1);
53|   canvas.width = Math.round(W * dpr);
54|   canvas.height = Math.round(H * dpr);
55|   canvas.style.width = W + "px";
56|   canvas.style.height = H + "px";
57|   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
58| }
59| window.addEventListener("resize", resize);
60| resize();
61| 
62| // ---- Palette ----
63| const COL_SLATE = "#2f3e3a";
64| const COL_CHALK = "#eeeae0";
65| const COL_ACCENT = "#f2c14e";
66| const COL_SECOND = "#8fc1e3";
67| 
68| // ---- Chalk drawing helpers ----
69| function wobble(amount) {
70|   return (Math.random() - 0.5) * amount;
71| }
72| 
73| function chalkLine(x1, y1, x2, y2, color, width) {
74|   ctx.lineCap = "round";
75|   ctx.lineJoin = "round";
76|   for (let i = 0; i < 2; i++) {
77|     const ox = wobble(1.2);
78|     const oy = wobble(1.2);
79|     ctx.globalAlpha = i === 0 ? 0.85 : 0.35;
80|     ctx.strokeStyle = color;
81|     ctx.lineWidth = width;
82|     ctx.beginPath();
83|     ctx.moveTo(x1 + ox + wobble(1.5), y1 + oy + wobble(1.5));
84|     ctx.lineTo(x2 + ox + wobble(1.5), y2 + oy + wobble(1.5));
85|     ctx.stroke();
86|   }
87|   ctx.globalAlpha = 1;
88| }
89| 
90| function chalkRect(x, y, w, h, color, width) {
91|   chalkLine(x, y, x + w, y, color, width);
92|   chalkLine(x + w, y, x + w, y + h, color, width);
93|   chalkLine(x + w, y + h, x, y + h, color, width);
94|   chalkLine(x, y + h, x, y, color, width);
95| }
96| 
97| function chalkHatchFill(x, y, w, h, color, spacing) {
98|   spacing = spacing || 8;
99|   ctx.save();
100|   ctx.beginPath();
101|   ctx.rect(x, y, w, h);
102|   ctx.clip();
103|   for (let i = -h; i < w + h; i += spacing) {
104|     chalkLine(x + i, y, x + i - h, y + h, color, 2.5);
105|   }
106|   ctx.restore();
107| }
108| 
109| function chalkCircle(cx, cy, r, color, width) {
110|   ctx.lineCap = "round";
111|   for (let pass = 0; pass < 2; pass++) {
112|     ctx.globalAlpha = pass === 0 ? 0.85 : 0.35;
113|     ctx.strokeStyle = color;
114|     ctx.lineWidth = width;
115|     ctx.beginPath();
116|     const segs = 24;
117|     for (let i = 0; i <= segs; i++) {
118|       const a = (i / segs) * Math.PI * 2;
119|       const rr = r + wobble(1.5);
120|       const px = cx + Math.cos(a) * rr + wobble(1);
121|       const py = cy + Math.sin(a) * rr + wobble(1);
122|       if (i === 0) ctx.moveTo(px, py);
123|       else ctx.lineTo(px, py);
124|     }
125|     ctx.stroke();
126|   }
127|   ctx.globalAlpha = 1;
128| }
129| 
130| function chalkText(text, x, y, size, color, align) {
131|   ctx.font = `${size}px "Comic Sans MS", cursive, sans-serif`;
132|   ctx.textAlign = align || "center";
133|   ctx.textBaseline = "middle";
134|   ctx.globalAlpha = 0.9;
135|   ctx.fillStyle = color;
136|   ctx.fillText(text, x + wobble(0.6), y + wobble(0.6));
137|   ctx.globalAlpha = 0.4;
138|   ctx.fillText(text, x + wobble(1) + 1, y + wobble(1) + 1);
139|   ctx.globalAlpha = 1;
140| }
141| 
142| // ---- Smudge layer ----
143| let smudges = [];
144| function initSmudges() {
145|   smudges = [];
146|   const n = 5;
147|   for (let i = 0; i < n; i++) {
148|     smudges.push({
149|       x: Math.random() * W,
150|       y: Math.random() * H,
151|       r: 80 + Math.random() * 160,
152|       a: 0.02 + Math.random() * 0.04,
153|     });
154|   }
155| }
156| function drawSmudges() {
157|   for (const s of smudges) {
158|     ctx.beginPath();
159|     ctx.fillStyle = COL_CHALK;
160|     ctx.globalAlpha = s.a;
161|     ctx.ellipse(s.x, s.y, s.r, s.r * 0.6, 0, 0, Math.PI * 2);
162|     ctx.fill();
163|     ctx.globalAlpha = 1;
164|   }
165| }
166| 
167| // ---- Game state ----
168| let paused = false;
169| let running = false; // becomes true after first tap (start)
170| let gameOver = false;
171| let stage = 0;
172| let score = 0;
173| let cells = []; // grid cells for current stage
174| let gridCols = 2, gridRows = 2;
175| let targetIndex = -1;
176| let stageStartTime = 0;
177| let timeLimit = 3000; // ms
178| let graceMs = 900; // grace period before threat can end stage
179| let stageDeadlineActive = false;
180| let flashTimer = 0;
181| let flashColor = null;
182| let resultMessage = "";
183| let lastFrameTime = 0;
184| 
185| const MAX_STAGE_FOR_GRID = 20;
186| 
187| function backToTitle() {
188|   running = false;
189|   gameOver = false;
190|   stage = 0;
191|   score = 0;
192|   paused = false;
193|   resultMessage = "";
194| }
195| 
196| function gridSizeForStage(s) {
197|   // stage 1: 2x2, grows slowly
198|   if (s <= 1) return { cols: 2, rows: 2 };
199|   if (s <= 3) return { cols: 2, rows: 3 };
200|   if (s <= 6) return { cols: 3, rows: 3 };
201|   if (s <= 10) return { cols: 3, rows: 4 };
202|   return { cols: 4, rows: 4 };
203| }
204| 
205| function timeLimitForStage(s) {
206|   // always "3 seconds" per plan loop, keep constant but shrink slightly at higher stages, floor at 1.4s
207|   const t = 3000 - (s - 1) * 80;
208|   return Math.max(1400, t);
209| }
210| 
211| function buildStage(s) {
212|   const size = gridSizeForStage(s);
213|   gridCols = size.cols;
214|   gridRows = size.rows;
215|   const total = gridCols * gridRows;
216|   targetIndex = Math.floor(Math.random() * total);
217|   cells = [];
218|   for (let i = 0; i < total; i++) {
219|     cells.push({ hit: false });
220|   }
221|   timeLimit = timeLimitForStage(s);
222|   stageStartTime = performance.now();
223|   stageDeadlineActive = false;
224|   // grace period before threat becomes active
225|   setTimeout(() => {
226|     if (!gameOver && running) stageDeadlineActive = true;
227|   }, graceMs);
228| }
229| 
230| function enterStage(next) {
231|   stage = next;
232|   buildStage(stage);
233|   CARTRIDGE.send("level", { index: stage });
234| }
235| 
236| function onGoalMet() {
237|   score += 1;
238|   CARTRIDGE.send("score", { value: score });
239|   flashColor = COL_SECOND;
240|   flashTimer = 250;
241|   enterStage(stage + 1);
242| }
243| 
244| function onStageFailed(reason) {
245|   gameOver = true;
246|   running = false;
247|   resultMessage = reason;
248|   flashColor = "#c96a5a";
249|   flashTimer = 400;
250|   CARTRIDGE.send("end", { reason: "lose" });
251| }
252| 
253| function layoutCellRects() {
254|   const margin = 40;
255|   const topPad = 140;
256|   const areaW = W - margin * 2;
257|   const areaH = H - topPad - margin;
258|   const gap = 12;
259|   const cw = (areaW - gap * (gridCols - 1)) / gridCols;
260|   const ch = (areaH - gap * (gridRows - 1)) / gridRows;
261|   const size = Math.min(cw, ch);
262|   const totalW = size * gridCols + gap * (gridCols - 1);
263|   const totalH = size * gridRows + gap * (gridRows - 1);
264|   const startX = margin + (areaW - totalW) / 2;
265|   const startY = topPad + (areaH - totalH) / 2;
266|   const rects = [];
267|   for (let r = 0; r < gridRows; r++) {
268|     for (let c = 0; c < gridCols; c++) {
269|       rects.push({
270|         x: startX + c * (size + gap),
271|         y: startY + r * (size + gap),
272|         w: size,
273|         h: size,
274|       });
275|     }
276|   }
277|   return rects;
278| }
279| 
280| function hitTestCell(px, py) {
281|   const rects = layoutCellRects();
282|   for (let i = 0; i < rects.length; i++) {
283|     const r = rects[i];
284|     if (px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h) {
285|       return i;
286|     }
287|   }
288|   return -1;
289| }
290| 
291| // ---- Input ----
292| canvas.addEventListener("pointerdown", (event) => {
293|   event.preventDefault();
294|   if (paused) return;
295|   if (!running && !gameOver) {
296|     running = true;
297|     CARTRIDGE.send("start");
298|     enterStage(1);
299|     return;
300|   }
301|   if (gameOver) {
302|     // tap to restart to title (soft reset behavior via tap)
303|     backToTitle();
304|     return;
305|   }
306|   if (!running) return;
307|   const rect = canvas.getBoundingClientRect();
308|   const px = event.clientX - rect.left;
309|   const py = event.clientY - rect.top;
310|   const idx = hitTestCell(px, py);
311|   if (idx === -1) return;
312|   if (idx === targetIndex) {
313|     onGoalMet();
314|   } else {
315|     onStageFailed("wrong");
316|   }
317| });
318| 
319| // ---- Draw functions ----
320| function drawTitleScreen(t) {
321|   drawSmudges();
322|   chalkText("Trois Secondes", W / 2, H / 2 - 60, Math.min(48, W / 10), COL_CHALK);
323|   const pulse = 0.6 + 0.4 * Math.sin(t / 300);
324|   ctx.globalAlpha = pulse;
325|   chalkText("Touche l'écran pour commencer", W / 2, H / 2 + 20, Math.min(24, W / 20), COL_ACCENT);
326|   ctx.globalAlpha = 1;
327|   chalkText("Trouve la bonne case avant la fin du temps !", W / 2, H / 2 + 70, Math.min(18, W / 26), COL_SECOND);
328| }
329| 
330| function drawGameOverScreen() {
331|   drawSmudges();
332|   chalkText("Partie terminée", W / 2, H / 2 - 60, Math.min(44, W / 11), COL_CHALK);
333|   chalkText("Score : " + score, W / 2, H / 2 + 0, Math.min(30, W / 15), COL_ACCENT);
334|   chalkText("Touche l'écran pour revenir", W / 2, H / 2 + 60, Math.min(20, W / 22), COL_SECOND);
335| }
336| 
337| function drawStage(t) {
338|   drawSmudges();
339| 
340|   // Header
341|   chalkText(`Étage ${stage}`, W / 2, 45, Math.min(32, W / 14), COL_CHALK);
342|   chalkText("Trouve la case marquée !", W / 2, 85, Math.min(20, W / 24), COL_SECOND);
343| 
344|   // Timer bar
345|   const elapsed = performance.now() - stageStartTime;
346|   const remaining = Math.max(0, timeLimit - Math.max(0, elapsed - graceMs));
347|   const frac = stageDeadlineActive ? remaining / timeLimit : 1;
348|   const barW = Math.min(420, W - 80);
349|   const barX = W / 2 - barW / 2;
350|   const barY = 105;
351|   chalkRect(barX, barY, barW, 14, COL_CHALK, 3);
352|   const fillColor = frac < 0.3 ? "#c96a5a" : COL_ACCENT;
353|   chalkHatchFill(barX + 2, barY + 2, Math.max(0, (barW - 4) * frac), 10, fillColor, 6);
354| 
355|   // Score
356|   chalkText("Score : " + score, W - 20, 30, 18, COL_CHALK, "right");
357| 
358|   // Grid
359|   const rects = layoutCellRects();
360|   for (let i = 0; i < rects.length; i++) {
361|     const r = rects[i];
362|     const isTarget = i === targetIndex;
363|     if (isTarget) {
364|       chalkHatchFill(r.x, r.y, r.w, r.h, COL_ACCENT, 10);
365|       chalkRect(r.x, r.y, r.w, r.h, COL_ACCENT, 4);
366|     } else {
367|       chalkRect(r.x, r.y, r.w, r.h, COL_CHALK, 3);
368|     }
369|   }
370| 
371|   // Check stage failure by timeout
372|   if (stageDeadlineActive && remaining <= 0 && !gameOver) {
373|     onStageFailed("timeout");
374|   }
375| }
376| 
377| function drawFlash(dt) {
378|   if (flashTimer > 0 && flashColor) {
379|     flashTimer -= dt;
380|     const alpha = Math.max(0, Math.min(0.35, flashTimer / 400 * 0.35));
381|     ctx.fillStyle = flashColor;
382|     ctx.globalAlpha = alpha;
383|     ctx.fillRect(0, 0, W, H);
384|     ctx.globalAlpha = 1;
385|   }
386| }
387| 
388| // ---- Main loop ----
389| function frame(t) {
390|   if (!lastFrameTime) lastFrameTime = t;
391|   const dt = t - lastFrameTime;
392|   lastFrameTime = t;
393| 
394|   ctx.fillStyle = COL_SLATE;
395|   ctx.fillRect(0, 0, W, H);
396| 
397|   if (paused) {
398|     drawSmudges();
399|     chalkText("Pause", W / 2, H / 2, 40, COL_CHALK);
400|     requestAnimationFrame(frame);
401|     return;
402|   }
403| 
404|   if (!running && !gameOver) {
405|     drawTitleScreen(t);
406|   } else if (gameOver) {
407|     drawGameOverScreen();
408|   } else {
409|     drawStage(t);
410|   }
411| 
412|   drawFlash(dt);
413| 
414|   requestAnimationFrame(frame);
415| }
416| 
417| // ---- Boot ----
418| initSmudges();
419| window.addEventListener("resize", initSmudges);
420| 
421| requestAnimationFrame((t) => {
422|   lastFrameTime = t;
423|   ctx.fillStyle = COL_SLATE;
424|   ctx.fillRect(0, 0, W, H);
425|   drawTitleScreen(t);
426|   CARTRIDGE.send("boot", { title: "Trois Secondes", gameType: "stage-clear", lang: "fr" });
427|   requestAnimationFrame(frame);
428| });
429| </script>
430| </body>
431| </html>
432|

